package solution

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"time"
)

type Release struct {
	ID        int
	Name      string
	Published time.Time
}

type ReleasePage struct {
	Items      []Release
	NextCursor int
}

func DecodeReleasePage(data []byte) (ReleasePage, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	page, err := decodePage(dec)
	if err != nil {
		return ReleasePage{}, fmt.Errorf("decode release page: %w", err)
	}

	var trailing json.RawMessage
	if err := dec.Decode(&trailing); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("trailing JSON value")
		}
		return ReleasePage{}, fmt.Errorf("decode release page: %w", err)
	}
	return page, nil
}

func decodePage(dec *json.Decoder) (ReleasePage, error) {
	if err := expectDelim(dec, '{'); err != nil {
		return ReleasePage{}, err
	}

	items := make([]Release, 0)
	var nextCursor int
	seenMembers := make(map[string]struct{}, 2)
	haveItems := false
	haveCursor := false

	for dec.More() {
		name, err := memberName(dec)
		if err != nil {
			return ReleasePage{}, err
		}
		if _, exists := seenMembers[name]; exists {
			return ReleasePage{}, fmt.Errorf("duplicate root member %q", name)
		}
		seenMembers[name] = struct{}{}

		switch name {
		case "items":
			items, err = decodeItems(dec)
			if err != nil {
				return ReleasePage{}, err
			}
			haveItems = true
		case "next_cursor":
			if err := decodeNonNull(dec, &nextCursor); err != nil {
				return ReleasePage{}, fmt.Errorf("invalid next_cursor: %w", err)
			}
			haveCursor = true
		default:
			return ReleasePage{}, fmt.Errorf("unknown root member %q", name)
		}
	}

	if err := expectDelim(dec, '}'); err != nil {
		return ReleasePage{}, err
	}
	if !haveItems || !haveCursor {
		return ReleasePage{}, fmt.Errorf("items and next_cursor are required")
	}
	if nextCursor < 0 {
		return ReleasePage{}, fmt.Errorf("next_cursor cannot be negative")
	}
	return ReleasePage{Items: items, NextCursor: nextCursor}, nil
}

func decodeItems(dec *json.Decoder) ([]Release, error) {
	if err := expectDelim(dec, '['); err != nil {
		return nil, fmt.Errorf("items must be an array: %w", err)
	}

	items := make([]Release, 0)
	seenIDs := make(map[int]struct{})
	for dec.More() {
		item, err := decodeRelease(dec)
		if err != nil {
			return nil, fmt.Errorf("item %d: %w", len(items), err)
		}
		if _, exists := seenIDs[item.ID]; exists {
			return nil, fmt.Errorf("duplicate id %d", item.ID)
		}
		seenIDs[item.ID] = struct{}{}
		items = append(items, item)
	}
	if err := expectDelim(dec, ']'); err != nil {
		return nil, err
	}
	return items, nil
}

func decodeRelease(dec *json.Decoder) (Release, error) {
	if err := expectDelim(dec, '{'); err != nil {
		return Release{}, fmt.Errorf("item must be an object: %w", err)
	}

	var id int
	var name string
	var publishedText string
	seenMembers := make(map[string]struct{}, 3)
	haveID := false
	haveName := false
	havePublished := false

	for dec.More() {
		member, err := memberName(dec)
		if err != nil {
			return Release{}, err
		}
		if _, exists := seenMembers[member]; exists {
			return Release{}, fmt.Errorf("duplicate item member %q", member)
		}
		seenMembers[member] = struct{}{}

		switch member {
		case "id":
			if err := decodeNonNull(dec, &id); err != nil {
				return Release{}, fmt.Errorf("invalid id: %w", err)
			}
			haveID = true
		case "name":
			if err := decodeNonNull(dec, &name); err != nil {
				return Release{}, fmt.Errorf("invalid name: %w", err)
			}
			haveName = true
		case "published":
			if err := decodeNonNull(dec, &publishedText); err != nil {
				return Release{}, fmt.Errorf("invalid published date: %w", err)
			}
			havePublished = true
		default:
			return Release{}, fmt.Errorf("unknown item member %q", member)
		}
	}

	if err := expectDelim(dec, '}'); err != nil {
		return Release{}, err
	}
	if !haveID || !haveName || !havePublished {
		return Release{}, fmt.Errorf("id, name, and published are required")
	}
	if id <= 0 {
		return Release{}, fmt.Errorf("id must be positive")
	}
	if name == "" {
		return Release{}, fmt.Errorf("name must be non-empty")
	}

	published, err := time.Parse("2006-01-02", publishedText)
	if err != nil || published.Format("2006-01-02") != publishedText {
		return Release{}, fmt.Errorf("invalid publication date")
	}
	return Release{ID: id, Name: name, Published: published}, nil
}

func memberName(dec *json.Decoder) (string, error) {
	tok, err := dec.Token()
	if err != nil {
		return "", err
	}
	name, ok := tok.(string)
	if !ok {
		return "", fmt.Errorf("object member name must be a string")
	}
	return name, nil
}

func expectDelim(dec *json.Decoder, want json.Delim) error {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	got, ok := tok.(json.Delim)
	if !ok || got != want {
		return fmt.Errorf("expected %q", want)
	}
	return nil
}

func decodeNonNull(dec *json.Decoder, dst any) error {
	var raw json.RawMessage
	if err := dec.Decode(&raw); err != nil {
		return err
	}
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return fmt.Errorf("null is not allowed")
	}
	if err := json.Unmarshal(raw, dst); err != nil {
		return err
	}
	return nil
}
